    snapshot_df, lock_df = sterile_fs_build_snapshot()

    snapshot = snapshot_df.iloc[0].to_dict() if not snapshot_df.empty else {}
    lock = lock_df.iloc[0].to_dict() if not lock_df.empty else {}

