@app.route("/sterile-compounding/sandbox-control-checklist")
def sterile_compounding_sandbox_control_checklist():
    blueprint_df, control_df = sterile_sb_build_registers()

    status_filter = sterile_sb_safe(sterile_sb_request.args.get("status", ""))
    system_filter = sterile_sb_safe(sterile_sb_request.args.get("system", ""))
    priority_filter = sterile_sb_safe(sterile_sb_request.args.get("priority", ""))

    filtered = control_df.copy()

    if status_filter and not filtered.empty:
        filtered = filtered[filtered["control_status"].astype(str) == status_filter]

    if system_filter and not filtered.empty:
        filtered = filtered[filtered["system_key"].astype(str) == system_filter]

    if priority_filter and not filtered.empty:
        filtered = filtered[filtered["control_priority"].astype(str) == priority_filter]

    total = len(filtered)
    green = int((filtered["control_status"] == "GREEN").sum()) if total else 0
    yellow = int((filtered["control_status"] == "YELLOW").sum()) if total else 0
    red = int((filtered["control_status"] == "RED").sum()) if total else 0
    p0 = int((filtered["control_priority"] == "P0").sum()) if total else 0

    status_options = ""
    for option in ["", "GREEN", "YELLOW", "RED"]:
        label = "All Control Statuses" if option == "" else option
        selected = "selected" if option == status_filter else ""
        status_options += f'<option value="{option}" {selected}>{label}</option>'

    system_options = '<option value="">All Systems</option>'
