    priority_options = ""
    for option in ["", "P0", "P1", "P2"]:
        label = "All Priorities" if option == "" else option
        selected = "selected" if option == priority_filter else ""
        priority_options += f'<option value="{option}" {selected}>{label}</option>'

    rows_html = ""

