    passport_id_source = {
        "passport_type": passport_type,
        "title": passport["title"],
        "score": passport["score"],
        "owner": passport["owner"],
        "generated_on": "2026-05-18",
        "source_engines": passport["source_engines"],
        "evidence_packets": passport["evidence_packets"]
    }

